/**
 * Syntax check of the generated scripts against the RouterOS 7.25 CLI reference (ROS_TABLE, generated by
 * scripts/ros-reference.ts): every menu must exist, every property a command sets or reads must be one of the menu's
 * arguments, read-only arguments or flags, and every special command (send, save, show-client-config…) must have its
 * page, with its own arguments. Values (enum choices, formats) are not checked.
 */
import { parseScript, type RosCommand } from "./ros-parse"
import { ROS_TABLE, ROS_VERSION } from "./ros-725"

/** Commands every directory or settings menu has, not documented as pages of their own. */
export const STANDARD_VERBS = new Set(["add", "set", "remove", "find", "get", "print", "export", "disable", "enable", "edit", "unset", "comment", "move", "reset-counters", "run"])

/** Arguments the standard commands take on any menu. */
const STANDARD_PROPS = new Set(["comment", "disabled", "place-before", "copy-from", "numbers", "file", "destination", "count-only", "where"])

/** Menus with no page of their own that only take a command whose page is checked (/export, /ip firewall export…). */
const COMMAND_ONLY = new Set(["/", "/ip firewall", "/routing", "/system backup"])

export type SyntaxIssue = { kind: "menu" | "prop" | "command"; menu: string; verb: string; item: string; line: number; text: string }

export function checkCommand(c: RosCommand): SyntaxIssue[] {
  const t = ROS_TABLE[c.menu]
  const issue = (kind: SyntaxIssue["kind"], item: string): SyntaxIssue => ({ kind, menu: c.menu, verb: c.verb, item, line: c.line, text: c.text })
  if (!t) return [issue("menu", c.menu)]
  if (!c.verb) {
    // A menu that is itself a command (/tool fetch url=…): its page's arguments.
    return c.props.filter((p) => !t.props.includes(p) && !STANDARD_PROPS.has(p)).map((p) => issue("prop", p))
  }
  if (!STANDARD_VERBS.has(c.verb) || t.commands[c.verb]) {
    const args = t.commands[c.verb]
    if (!args) return [issue("command", c.verb)]
    return c.props.filter((p) => !args.includes(p) && !t.props.includes(p) && !STANDARD_PROPS.has(p)).map((p) => issue("prop", p))
  }
  if (COMMAND_ONLY.has(c.menu) && !["export", "import"].includes(c.verb)) return [issue("command", c.verb)]
  return c.props.filter((p) => !t.props.includes(p) && !STANDARD_PROPS.has(p)).map((p) => issue("prop", p))
}

/** Every issue in a script (one-liners, [ ] substitutions and stored scripts included). */
export function checkScript(script: string): SyntaxIssue[] {
  return parseScript(script).flatMap(checkCommand)
}

export { ROS_VERSION }
